function getNodeResult(nodeName) {
  try {
    const nodeItems = $(nodeName).all();
    if (nodeItems && nodeItems.length > 0) {
      return nodeItems[0].json || {};
    }
    return {};
  } catch (e) {
    return {};
  }
}

// Fetch raw responses
const binanceRaw = getNodeResult("Fetch Binance Orderbook & 24h Data");
const geckoRaw = getNodeResult("Fetch CoinGecko BTC/USD");
const krakenRaw = getNodeResult("Fetch Kraken Ticker Data");
const coinbaseRaw = getNodeResult("Fetch Coinbase BTC/USD");
const kucoinRaw = getNodeResult("Fetch KuCoin Orderbook Data");

// Extract Prices
const binanceAsk = parseFloat(binanceRaw.asks?.[0]?.[0] || binanceRaw.price || 0);
const binanceBid = parseFloat(binanceRaw.bids?.[0]?.[0] || binanceRaw.price || 0);
const binancePrice = (binanceAsk + binanceBid) / 2 || parseFloat(binanceRaw.price || 0);

const geckoPrice = parseFloat(geckoRaw.bitcoin?.usd || 0);
const geckoAsk = geckoPrice;
const geckoBid = geckoPrice;

const krakenData = krakenRaw.result?.XXBTZUSD || krakenRaw.result?.XBTUSD || {};
const krakenAsk = parseFloat(krakenData.a?.[0] || 0);
const krakenBid = parseFloat(krakenData.b?.[0] || 0);
const krakenPrice = parseFloat(krakenData.c?.[0] || (krakenAsk + krakenBid) / 2 || 0);

const coinbasePrice = parseFloat(coinbaseRaw.data?.amount || 0);
const coinbaseAsk = coinbasePrice;
const coinbaseBid = coinbasePrice;

const kucoinAsk = parseFloat(kucoinRaw.data?.bestAsk || kucoinRaw.data?.price || 0);
const kucoinBid = parseFloat(kucoinRaw.data?.bestBid || kucoinRaw.data?.price || 0);
const kucoinPrice = parseFloat(kucoinRaw.data?.price || (kucoinAsk + kucoinBid) / 2 || 0);

const exchanges = [
  { exchange: "Binance", price: binancePrice, ask: binanceAsk, bid: binanceBid },
  { exchange: "CoinGecko", price: geckoPrice, ask: geckoAsk, bid: geckoBid },
  { exchange: "Kraken", price: krakenPrice, ask: krakenAsk, bid: krakenBid },
  { exchange: "Coinbase", price: coinbasePrice, ask: coinbaseAsk, bid: coinbaseBid },
  { exchange: "KuCoin", price: kucoinPrice, ask: kucoinAsk, bid: kucoinBid }
].filter(p => p.price > 0 && !isNaN(p.price) && p.ask > 0 && p.bid > 0);

if (exchanges.length < 2) {
  throw new Error(`Unable to parse enough valid exchange prices.`);
}

const minExchange = exchanges.reduce((min, p) => p.ask < min.ask ? p : min, exchanges[0]);
const maxExchange = exchanges.reduce((max, p) => p.bid > max.bid ? p : max, exchanges[0]);

const buyPrice = minExchange.ask;
const sellPrice = maxExchange.bid;

// Fee Calculations (1 BTC Basis)
const buyFeeRate = 0.001;
const sellFeeRate = 0.001;
const btcTransferFee = 0.0002;

const buyFeeUSD = buyPrice * buyFeeRate;
const sellFeeUSD = sellPrice * sellFeeRate;
const transferFeeUSD = btcTransferFee * buyPrice;
const totalFeesUSD = buyFeeUSD + sellFeeUSD + transferFeeUSD;

const rawSpread = sellPrice - buyPrice;
const netProfitAmount = rawSpread - totalFeesUSD;
const netProfitPercentage = buyPrice > 0 ? (netProfitAmount / buyPrice) * 100 : 0;
const spreadPercentage = buyPrice > 0 ? (rawSpread / buyPrice) * 100 : 0;

return [{
  json: {
    binancePrice,
    geckoPrice,
    krakenPrice,
    coinbasePrice,
    kucoinPrice,
    minExchange: minExchange.exchange,
    minPrice: buyPrice,
    maxExchange: maxExchange.exchange,
    maxPrice: sellPrice,
    rawSpread: parseFloat(rawSpread.toFixed(2)),
    spreadPercentage: parseFloat(spreadPercentage.toFixed(4)),
    buyFeeUSD: parseFloat(buyFeeUSD.toFixed(2)),
    sellFeeUSD: parseFloat(sellFeeUSD.toFixed(2)),
    transferFeeUSD: parseFloat(transferFeeUSD.toFixed(2)),
    totalFeesUSD: parseFloat(totalFeesUSD.toFixed(2)),
    netProfitAmount: parseFloat(netProfitAmount.toFixed(2)),
    netProfitPercentage: parseFloat(netProfitPercentage.toFixed(4)),
    isNetProfitable: netProfitAmount > 0,
    timestamp: new Date().toISOString()
  }
}];
